source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    cells = {(r, c) for r in range(height) for c in range(width) if grid[r][c] == 8}
    pieces = []

    for r in range(height - 1):
        for c in range(width - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            square = set(corners)
            if square <= cells:
                pieces.append((square, 1))
            for missing, color in ((0, 2), (2, 3), (1, 4)):
                shape = square - {corners[missing]}
                if shape <= cells:
                    pieces.append((shape, color))

    by_cell = {cell: [] for cell in cells}
    for index, (shape, _) in enumerate(pieces):
        for cell in shape:
            by_cell[cell].append(index)

    output = [[0] * width for _ in range(height)]

    def cover(remaining):
        if not remaining:
            return True
        cell = min(remaining, key=lambda p: sum(pieces[i][0] <= remaining for i in by_cell[p]))
        for index in by_cell[cell]:
            shape, color = pieces[index]
            if shape <= remaining:
                for r, c in shape:
                    output[r][c] = color
                if cover(remaining - shape):
                    return True
                for r, c in shape:
                    output[r][c] = 0
        return False

    if cover(cells):
        return output
    return [row[:] for row in grid]
'''
